//! What ResuFlow is licensed under, and the notices of everything it ships, compiled in so the
//! app can always show them (About → Licenses). `THIRD_PARTY_LICENSES.md` is generated by
//! `npm run licenses` from the dependencies actually built in; CI fails if it is out of date.
//! The app shows it as a list, so it is parsed here into packages and the texts they cite.

use serde::Serialize;

pub const LICENSE_ID: &str = "Apache-2.0";
pub const LICENSE: &str = include_str!("../../LICENSE");
pub const NOTICE: &str = include_str!("../../NOTICE");
pub const THIRD_PARTY: &str = include_str!("../../THIRD_PARTY_LICENSES.md");

#[derive(Serialize)]
pub struct Licenses {
    pub id: &'static str,
    pub license: &'static str,
    pub notice: &'static str,
    pub third_party: ThirdParty,
}

/// `THIRD_PARTY_LICENSES.md`, taken apart. Prose stays Markdown (paragraphs, inline code);
/// license texts are verbatim.
#[derive(Serialize, Default)]
pub struct ThirdParty {
    /// Sections of prose, in order; the first is the untitled preamble.
    pub prose: Vec<Prose>,
    /// License id and how many packages use it.
    pub summary: Vec<(String, usize)>,
    pub groups: Vec<Group>,
    /// Package `texts` index into this, 0-based.
    pub texts: Vec<Text>,
}

#[derive(Serialize, Default)]
pub struct Prose {
    pub title: String,
    pub paragraphs: Vec<String>,
}

#[derive(Serialize)]
pub struct Group {
    pub title: String,
    pub note: String,
    pub packages: Vec<Package>,
}

#[derive(Serialize)]
pub struct Package {
    pub name: String,
    /// Why a package that isn't a dependency is listed, if it is one.
    pub note: String,
    /// The platforms it is used on, empty for all.
    pub platforms: String,
    pub version: String,
    pub declared: String,
    pub used: String,
    pub source: String,
    pub texts: Vec<usize>,
}

#[derive(Serialize)]
pub struct Text {
    pub kind: String,
    pub users: usize,
    pub text: String,
}

pub fn licenses() -> Licenses {
    Licenses { id: LICENSE_ID, license: LICENSE, notice: NOTICE, third_party: third_party(THIRD_PARTY) }
}

/// Split a table row into cells, honouring `\|` escapes.
fn cells(row: &str) -> Vec<String> {
    let inner = row.trim().trim_start_matches('|').trim_end_matches('|');
    let mut out = vec![String::new()];
    let mut chars = inner.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' if chars.peek() == Some(&'|') => out.last_mut().unwrap().push(chars.next().unwrap()),
            '|' => out.push(String::new()),
            _ => out.last_mut().unwrap().push(c),
        }
    }
    out.into_iter().map(|c| c.trim().to_string()).collect()
}

/// `name (note) · platforms`
fn package(c: &[String]) -> Package {
    let (rest, platforms) = c[0].split_once(" · ").unwrap_or((&c[0], ""));
    let (name, note) = match rest.split_once(" (") {
        Some((n, note)) if note.ends_with(')') => (n, &note[..note.len() - 1]),
        _ => (rest, ""),
    };
    let texts = c[5]
        .split(", ")
        .filter_map(|r| r.strip_prefix('[')?.split(']').next()?.parse::<usize>().ok())
        .map(|n| n - 1)
        .collect();
    Package {
        name: name.into(),
        note: note.into(),
        platforms: platforms.into(),
        version: c[1].clone(),
        declared: c[2].clone(),
        used: c[3].clone(),
        source: c[4].clone(),
        texts,
    }
}

pub fn third_party(md: &str) -> ThirdParty {
    let mut tp = ThirdParty { prose: vec![Prose::default()], ..Default::default() };
    let mut section = String::new();
    let mut paragraph: Vec<&str> = Vec::new();
    let mut lines = md.lines();

    // A finished paragraph goes to the current package group's note, or the current prose section.
    let flush = |tp: &mut ThirdParty, paragraph: &mut Vec<&str>, section: &str| {
        if paragraph.is_empty() {
            return;
        }
        let text = paragraph.join(" ");
        paragraph.clear();
        match tp.groups.last_mut().filter(|g| g.title == section_title(section)) {
            Some(g) if !g.note.is_empty() => g.note = format!("{}\n\n{text}", g.note),
            Some(g) => g.note = text,
            None => tp.prose.last_mut().unwrap().paragraphs.push(text),
        }
    };

    while let Some(line) = lines.next() {
        if let Some(title) = line.strip_prefix("## ") {
            flush(&mut tp, &mut paragraph, &section);
            section = title.into();
            match title {
                "Summary" | "License texts" => {}
                _ if is_group(title) => {
                    tp.groups.push(Group { title: section_title(title).into(), note: String::new(), packages: Vec::new() })
                }
                _ => tp.prose.push(Prose { title: title.into(), paragraphs: Vec::new() }),
            }
        } else if section == "License texts" {
            let Some(head) = line.strip_prefix("### ") else { continue };
            let kind = head.split_once(". ").map_or(head, |(_, k)| k).to_string();
            let (mut users, mut text) = (0, Vec::new());
            while let Some(l) = lines.next() {
                if let Some(u) = l.strip_prefix("Used by: ") {
                    users = u.split(", ").count();
                } else if l == "````text" {
                    text = lines.by_ref().take_while(|t| *t != "````").collect();
                    break;
                }
            }
            tp.texts.push(Text { kind, users, text: text.join("\n") });
        } else if line.starts_with('|') {
            let c = cells(line);
            if c[0] == "License" || c[0] == "Package" || c[0].starts_with("---") {
                continue;
            }
            if section == "Summary" {
                tp.summary.push((c[0].clone(), c[1].parse().unwrap_or(0)));
            } else if is_group(&section) {
                tp.groups.last_mut().unwrap().packages.push(package(&c));
            }
        } else if line.trim().is_empty() {
            flush(&mut tp, &mut paragraph, &section);
        } else if section != "Summary" && !line.starts_with("# ") {
            paragraph.push(line.trim());
        }
    }
    flush(&mut tp, &mut paragraph, &section);
    tp
}

/// A package table's section is titled with its count: `Rust crates (366)`.
fn is_group(title: &str) -> bool {
    title.rsplit_once(" (").is_some_and(|(_, n)| n.strip_suffix(')').is_some_and(|n| n.parse::<usize>().is_ok()))
}

fn section_title(title: &str) -> &str {
    if is_group(title) { title.rsplit_once(" (").unwrap().0 } else { title }
}

#[cfg(test)]
mod tests {
    #[test]
    fn notices_are_present() {
        assert!(super::LICENSE.contains("Apache License") && super::LICENSE.contains("Version 2.0"));
        assert!(super::NOTICE.starts_with("ResuFlow"));
        assert!(super::THIRD_PARTY.contains("tauri") && super::THIRD_PARTY.contains("@codemirror/view"));
    }

    /// Nothing in the generated file is lost on the way to the app.
    #[test]
    fn third_party_parses_completely() {
        let md = super::THIRD_PARTY;
        let tp = super::third_party(md);

        // Every package row, and each group's stated count.
        let rows = md.lines().filter(|l| l.starts_with("| ") && l.contains("](#text-")).count();
        assert_eq!(tp.groups.iter().map(|g| g.packages.len()).sum::<usize>(), rows);
        for g in &tp.groups {
            assert!(md.contains(&format!("## {} ({})\n", g.title, g.packages.len())), "{}", g.title);
        }
        assert!(tp.groups.iter().any(|g| g.packages.iter().any(|p| p.name == "tauri")));
        let vite = tp.groups.iter().flat_map(|g| &g.packages).find(|p| p.name == "vite").unwrap();
        assert!(vite.note.contains("module-preload"));
        assert!(tp.groups.iter().flat_map(|g| &g.packages).any(|p| p.platforms.contains("Linux")));

        // Every text, verbatim, and every reference resolves; every text is cited.
        assert_eq!(tp.texts.len(), md.matches("\n````text\n").count());
        for t in &tp.texts {
            assert!(!t.text.is_empty() && t.users > 0);
            assert!(md.contains(&format!("````text\n{}\n````", t.text)));
        }
        let mut cited = vec![false; tp.texts.len()];
        for p in tp.groups.iter().flat_map(|g| &g.packages) {
            assert!(!p.texts.is_empty(), "{}", p.name);
            for &i in &p.texts {
                cited[i] = true;
            }
        }
        assert!(cited.iter().all(|&c| c));

        // The summary and the prose, including the operating-system libraries.
        assert_eq!(
            tp.summary.iter().map(|s| s.1).sum::<usize>(),
            tp.groups.iter().flat_map(|g| &g.packages).map(|p| p.used.split(" AND ").count()).sum::<usize>()
        );
        assert!(tp.prose[0].title.is_empty() && tp.prose[0].paragraphs[0].starts_with("ResuFlow is licensed"));
        let os = tp.prose.iter().find(|p| p.title == "Supplied by the operating system").unwrap();
        assert!(os.paragraphs.iter().any(|p| p.contains("LGPL 2.1") && p.contains("on request")));
        assert_eq!(tp.groups[1].note, "Bundled into the app's interface.");
    }
}
